_sage_const_0 = Integer(0); _sage_const_4 = Integer(4); _sage_const_1 = Integer(1); _sage_const_5 = Integer(5); _sage_const_7 = Integer(7); _sage_const_11 = Integer(11); _sage_const_126 = Integer(126); _sage_const_344 = Integer(344); _sage_const_1332 = Integer(1332); _sage_const_12096 = Integer(12096); _sage_const_2 = Integer(2); _sage_const_96 = Integer(96); _sage_const_50000 = Integer(50000); _sage_const_57734208 = Integer(57734208); _sage_const_4773 = Integer(4773); _sage_const_500 = Integer(500)# eabc_mu5711_production.sage
